# ponytail: ключові слова по назві товару; достатньо для топ-100
STAGE_RULES = [
    ("lipoland",   ["lipoland", "ліполенд", "pecs", "пекс", "візуальний розклад", "книжечка на липучках", "пластилін"]),
    ("pregnant",   ["для вагітних", "подушка для годування", "feeding pillow", "бюстгальтер", "пдр", "znana", "для годуючих", "для годування sport", "халат"]),
    ("m0_3",       ["слінг", "пелюшка", "кокон", "накладки для смоктання"]),
    ("m3_6",       ["ерго-рюкзак", "рюкзак adapted", "розмір 1", "хіпсіт"]),
    ("m6_12",      ["стільчик", "стілець для годування", "memoram", "тарілка", "накидка для годування", "прорізувач", "розмір 2"]),
]

def infer_stage(items):
    text = " ".join(items).lower()
    for stage, kws in STAGE_RULES:
        if any(k in text for k in kws):
            return stage
    return "unknown"

